function validate([m, n, coordinates]) {
  if (!Number.isInteger(m) || m < 2 || m > 100000) return 'm is between 2 and 10^5.';
  if (!Number.isInteger(n) || n < 2 || n > 100000) return 'n is between 2 and 10^5.';
  if (!Array.isArray(coordinates) || coordinates.length > 10000) return 'coordinates has at most 10^4 cells.';
  const seen = new Set();
  for (const cell of coordinates) {
    if (!Array.isArray(cell) || cell.length !== 2) return 'Each coordinate is a pair [x, y].';
    const [x, y] = cell;
    if (!Number.isInteger(x) || x < 0 || x >= m) return 'Each x is between 0 and m - 1.';
    if (!Number.isInteger(y) || y < 0 || y >= n) return 'Each y is between 0 and n - 1.';
    const key = x * n + y;
    if (seen.has(key)) return 'Each cell may appear only once.';
    seen.add(key);
  }
  return null;
}

