function countBlackBlocks(m, n, coordinates) {
  // Every block that holds a black cell has its top-left corner next to one; check each such block cell by cell.
  const corners = new Set();
  for (const [x, y] of coordinates)
    for (const [dx, dy] of [[0, 0], [-1, 0], [0, -1], [-1, -1]]) {
      const r = x + dx, c = y + dy;
      if (r >= 0 && c >= 0 && r + 1 < m && c + 1 < n) corners.add(r + ',' + c);
    }
  const arr = [0, 0, 0, 0, 0];
  for (const corner of corners) {
    const [r, c] = corner.split(',').map(Number);
    let black = 0;
    for (const [x, y] of coordinates)
      if ((x === r || x === r + 1) && (y === c || y === c + 1)) black++;
    arr[black]++;
  }
  arr[0] = (m - 1) * (n - 1) - corners.size;
  return arr;
}

