function generate(rand, size) {
  const style = Math.floor(rand() * 3);
  let m, n, k, rowSpan, colSpan;
  if (size === 'small') {
    m = 2 + Math.floor(rand() * 4);
    n = 2 + Math.floor(rand() * 4);
    k = Math.floor(rand() * (Math.min(m * n, 10) + 1));
    rowSpan = m;
    colSpan = n;
  } else if (style === 0) {
    m = 40 + Math.floor(rand() * 30);
    n = 40 + Math.floor(rand() * 30);
    k = 2000;
    rowSpan = m;
    colSpan = n;
  } else if (style === 1) {
    m = 90000 + Math.floor(rand() * 10001);
    n = 90000 + Math.floor(rand() * 10001);
    k = 2000;
    rowSpan = 60;
    colSpan = 60;
  } else {
    m = 2 + Math.floor(rand() * 99999);
    n = 2 + Math.floor(rand() * 99999);
    k = Math.min(2000, Math.floor(m * n / 2));
    rowSpan = m;
    colSpan = n;
  }
  const rowStart = Math.floor(rand() * (m - rowSpan + 1));
  const colStart = Math.floor(rand() * (n - colSpan + 1));
  const seen = new Set();
  const coordinates = [];
  while (coordinates.length < k) {
    const x = rowStart + Math.floor(rand() * rowSpan);
    const y = colStart + Math.floor(rand() * colSpan);
    const key = x * n + y;
    if (seen.has(key)) continue;
    seen.add(key);
    coordinates.push([x, y]);
  }
  return [m, n, coordinates];
}
